/**
 * @summary How trustworthy seat availability currently is for a term (live / cached / not connected)
 */
export const GetSectionAvailabilityStatusQueryParams = zod.object({
  term: zod.enum(["fall", "winter", "spring", "summer"]),
  year: zod.coerce.number(),
});

export const GetSectionAvailabilityStatusResponse = zod.object({
  term: zod.string(),
  year: zod.number(),
  state: zod
    .enum([
      "live",
      "cached",
      "stale",
      "unavailable",
      "not_connected",
      "sample",
      "manual_snapshot",
    ])
    .describe(
      "What the section picker may say about seat data for this term: live\/cached\/stale = a live feed is connected (cached and stale mean serving an older answer); unavailable = a live feed is configured but cannot be reached; not_connected = no live feed and no seat data; manual_snapshot = only the data steward's paste; sample = development fixture data.",
    ),
  liveConfigured: zod.boolean(),
  lastUpdatedAt: zod.coerce.date().nullable(),
  sectionsWithKnownAvailability: zod.number(),
  counts: zod.object({
    open: zod.number(),
    waitlist: zod.number(),
    full: zod.number(),
    unknown: zod.number(),
  }),
});

/**
 * Accepts text copied from SCU's Workday "Find Course Sections" view.
 * The user's Workday password is never sent to or stored by the server —
 * only the visible section table is parsed and saved. Re-syncing the
 * same term overwrites prior rows for that term.
 * @summary Parse pasted Workday section data and upsert into the database
 */
export const syncWorkdaySectionsBodyYearMin = 2024;
export const syncWorkdaySectionsBodyYearMax = 2030;

export const syncWorkdaySectionsBodyReplaceTermDefault = true;

export const SyncWorkdaySectionsBody = zod.object({
  rawText: zod
    .string()
    .describe("Raw text\/HTML pasted from Workday's Find Course Sections view"),
  term: zod.enum(["fall", "winter", "spring", "summer"]),
  year: zod
    .number()
    .min(syncWorkdaySectionsBodyYearMin)
    .max(syncWorkdaySectionsBodyYearMax),
  replaceTerm: zod
    .boolean()
    .default(syncWorkdaySectionsBodyReplaceTermDefault)
    .describe(
      "If true, delete all existing sections for this term\/year before inserting parsed rows",
    ),
});

export const SyncWorkdaySectionsResponse = zod.object({
  parsedCount: zod.number(),
  insertedCount: zod.number(),
  deletedCount: zod.number(),
  term: zod.enum(["fall", "winter", "spring", "summer"]),
  year: zod.number(),
  sampleSections: zod
    .array(
      zod.object({
        id: zod.string().describe('e.g. \"COEN-12-01-fall-2025\"'),
        courseCode: zod.string(),
        sectionNumber: zod.string(),
        term: zod.enum(["fall", "winter", "spring", "summer"]),
        year: zod.number(),
        instructor: zod.string(),
        meetingDays: zod.array(zod.enum(["M", "T", "W", "R", "F", "S", "U"])),
        startTime: zod.string().describe("24h HH:mm"),
        endTime: zod.string().describe("24h HH:mm"),
        location: zod.string(),
        seatsTotal: zod.number(),
        seatsOpen: zod.number(),
        waitlist: zod.number(),
        seatsKnown: zod
          .boolean()
          .optional()
          .describe(
            "True when live seat counts are available (pasted from Workday). False for the official Registrar schedule, which lists offerings\/times but not seats.",
          ),
        tentative: zod
          .boolean()
          .optional()
          .describe(
            "True for tentative-schedule terms (Winter\/Spring 2027) where section numbers and instructors are not yet finalized.",
          ),
        componentType: zod
          .enum(["lecture", "lab", "discussion", "recitation", "unknown"])
          .optional()
          .describe(
            'Which course component this section is. When the source states an instructional format it is used as-is; otherwise it is derived from how the course\'s own sections meet in that term. \"unknown\" means CampusVal could not tell.',
          ),
        componentInferred: zod
          .boolean()
          .optional()
          .describe(
            "True when componentType was derived from the meeting pattern; false when the source published it.",
          ),
        componentSourceLabel: zod
          .string()
          .nullish()
          .describe(
            "The instructional format exactly as the source printed it, when it did.",
          ),
        availabilityStatus: zod
          .enum(["open", "waitlist", "full", "unknown"])
          .describe(
            'Derived from seatsKnown\/seatsOpen\/waitlist, never fabricated. \"unknown\" whenever seatsKnown is false (including every tentative Winter\/Spring term, which never carries seat data). CampusVal has no source that distinguishes an instructor-closed section from a merely-full one, so both collapse to \"full\" rather than inventing a fifth state without evidence — see docs\/SECTION_AVAILABILITY.md.',
          ),
        lastUpdatedAt: zod.coerce
          .date()
          .nullable()
          .describe(
            "When the SOURCE says this section's seat data was true (the live feed's own timestamp, or the data steward's paste time). Null when no source has said anything (the official Registrar schedule has no seat data).",
          ),
        sourceType: zod
          .enum([
            "workday_live",
            "workday_self_paste",
            "registrar_schedule",
            "fixture",
          ])
          .describe(
            "Where this section's availability comes from. workday_live only for a real authorized upstream feed; workday_self_paste is a manual snapshot by the data steward (never live); fixture is development sample data (never served in production); registrar_schedule means no seat data at all. See docs\/SECTION_AVAILABILITY.md.",
          ),
        sourceLabel: zod
          .string()
          .describe(
            "Human-readable source label to render next to lastUpdatedAt.",
          ),
        isLive: zod
          .boolean()
          .describe(
            'True ONLY for a real, authorized, recently refreshed live feed. The UI must show a \"Live\" badge iff this is true.',
          ),
        freshness: zod
          .enum(["live", "cached", "stale", "unavailable"])
          .describe(
            'How far the timestamp can be trusted. \"stale\" and \"unavailable\" always come with availabilityStatus \"unknown\" — an old \"open\" is never presented as open.',
          ),
      }),
    )
    .describe("First 5 parsed sections for confirmation in the UI"),
  errors: zod.array(
    zod.object({
      line: zod.string(),
      reason: zod.string(),
    }),
  ),
});

